mapper.update:
UPDATE hr_final_settlement SET status = 'CLOSED',
  calculation_snapshot = #{record.calculationSnapshot,typeHandler=com.baomidou.mybatisplus.extension.handlers.JacksonTypeHandler},
  version = version + 1, update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE tenant_id = #{record.tenantId} AND settlement_id = #{record.settlementId} AND employee_id = #{record.employeeId}
  AND status = 'PAID' AND approval_status = 'APPROVED' AND superseded_flag = 0
  AND ((settlement_kind = 'NORMAL' AND reversal_of_id IS NULL) OR (settlement_kind = 'REVERSAL' AND reversal_of_id IS NOT NULL))
  AND confirmed_time IS NOT NULL AND paid_time IS NOT NULL AND version = #{expectedVersion}

UPDATE hr_final_settlement SET status = #{record.status}, payment_request_id = #{record.paymentRequestId},
    settlement_proof_file_id = #{record.settlementProofFileId}, paid_time = #{record.paidTime},
    calculation_snapshot = #{record.calculationSnapshot,typeHandler=com.baomidou.mybatisplus.extension.handlers.JacksonTypeHandler},
    version = version + 1, update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE tenant_id = #{record.tenantId} AND settlement_id = #{record.settlementId} AND employee_id = #{record.employeeId}
  AND status = 'CONFIRMED' AND approval_status = 'APPROVED' AND superseded_flag = 0
  AND ((settlement_kind = 'NORMAL' AND reversal_of_id IS NULL) OR (settlement_kind = 'REVERSAL' AND reversal_of_id IS NOT NULL))
  AND confirmed_time IS NOT NULL AND confirmed_by IS NOT NULL AND paid_time IS NULL AND version = #{expectedVersion}
